"""Bundled CSS for the read-only Command Center."""

CSS = """:root{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#e9f1fb;background:#09111b;font-size:14px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0}
.shell{display:flex;min-height:100vh}.sidebar{width:256px;position:sticky;top:0;height:100vh;padding:28px 18px;background:#101d2d;border-right:1px solid #263a50;display:flex;flex-direction:column;gap:36px;flex-shrink:0}
.brand{display:flex;gap:12px;align-items:center;color:white}.brand strong{font-size:16px;letter-spacing:.14em}.brand small{display:block;color:#809eb7;font-size:10px;letter-spacing:.1em;margin-top:5px}
.logo{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,#296681,#163650);color:#7ce3f2;font-size:28px}
.nav{display:grid;gap:8px}.nav a{padding:14px 12px;color:#a5b8cb;text-decoration:none;border-radius:10px;line-height:1.5}.nav a:hover{background:#1b3349;color:#d6f5ff}
.sidebar-foot{margin-top:auto;color:#a9c4d4;font-size:11px;letter-spacing:.11em}.sidebar-foot small{display:block;letter-spacing:0;margin-top:10px;color:#778fa5}.dot{width:9px;height:9px;display:inline-block;border-radius:50%;background:#59cba3;margin-right:8px;box-shadow:0 0 12px #59cba3}
.main{max-width:1450px;width:100%;margin:0 auto;padding:40px clamp(24px,4vw,66px)}header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:25px}.eyebrow{color:#66bed9;letter-spacing:.16em;font-size:11px;font-weight:700}h1{font-weight:750;margin:10px 0 12px;font-size:clamp(26px,3vw,39px)}h1 em{font-style:normal;color:#7fe1e8}header p{color:#9fb5c8;line-height:1.6;margin:0;max-width:670px}
button{border:1px solid #33627a;background:#1c4661;color:#e8faff;padding:12px 19px;border-radius:9px;cursor:pointer;font-weight:700}button:hover{background:#245674}button:disabled{opacity:.5;cursor:wait}.notification{padding:12px 16px;background:#12332f;border:1px solid #2b7869;color:#9cf6d8;border-radius:10px}.notification.error{background:#3e2229;color:#ffd0d1;border-color:#8f3c49}
section{margin-top:38px;scroll-margin-top:20px}.section-title{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:16px}.section-title h2{font-size:19px;margin:0}.section-title span{color:#829db6;font-size:12px}
.metric-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.metric,.panel,.feature-grid article{background:#142333;border:1px solid #2a3d51;border-radius:14px}.metric{padding:22px;min-height:135px}.metric span{color:#9ab1c8;font-size:12px}.metric strong{display:block;font-size:30px;color:#d5f3fc;margin:13px 0 8px}.metric small{color:#7892a8}
.panel{padding:23px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.panel-head small,.disclaimer{color:#8ca9bf;font-size:12px;line-height:1.6}
.vision-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:15px;margin-top:18px}.vision-card{border:1px solid #33495a;border-radius:11px;padding:9px;background:#0c1b29}.vision-card img{width:100%;aspect-ratio:4/3;object-fit:contain;background:#09111b;border-radius:7px}.vision-card strong{font-size:12px;display:block;margin:11px 3px 5px;overflow-wrap:anywhere}.vision-card small{color:#859bac;display:block;margin:0 3px 6px;overflow-wrap:anywhere}
.muted{color:#8eacc2}.row{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #2b4052;gap:12px}.row span{color:#aac0d2}.row strong{color:#e5f7ff}.events{margin-top:18px;display:flex;flex-wrap:wrap;gap:8px}.event-tag{border:1px solid #31546b;padding:7px 10px;border-radius:8px;color:#b4d6e9;font-size:11px}
.harness p{color:#94abc1;max-width:800px;line-height:1.6}.harness code{font-size:12px;color:#8cdecf;overflow-wrap:anywhere}.harness button{display:block;margin:20px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:15px;background:#0a1621;border-radius:9px;font-size:12px;color:#aad4e4;max-height:310px;overflow:auto}
.feature-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.feature-grid article{padding:18px;min-height:113px}.feature-grid strong{display:block;margin-bottom:12px}.feature-grid small{color:#8faec3;line-height:1.5}
footer{color:#65829c;border-top:1px solid #23394b;margin-top:40px;padding-top:22px;font-size:12px}
@media(max-width:1080px){.metric-grid{grid-template-columns:repeat(2,1fr)}.feature-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:720px){.shell{display:block}.sidebar{width:100%;height:auto;position:static;gap:15px}.nav{grid-template-columns:repeat(2,minmax(0,1fr));gap:3px}.nav a{padding:8px;font-size:12px}.sidebar-foot{display:none}.main{padding:25px 15px}header{align-items:flex-start;flex-wrap:wrap}.metric-grid,.feature-grid{grid-template-columns:1fr 1fr}.section-title{align-items:flex-start;flex-direction:column}}
@media(max-width:440px){.metric-grid,.feature-grid{grid-template-columns:1fr}.vision-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
"""
